static readonly HashSet<string> AllowedHosts = new(StringComparer.OrdinalIgnoreCase)
{
    "hooks.example.com",
    "webhooks.trusted-partner.com"
};

app.MapPost("/api/webhooks", async (string callbackUrl, HttpClient http) =>
{
    if (!Uri.TryCreate(callbackUrl, UriKind.Absolute, out var uri))
        return Results.BadRequest("Invalid URL");

    if (uri.Scheme != "https")
        return Results.BadRequest("Only HTTPS URLs are allowed");

    if (!AllowedHosts.Contains(uri.Host))
        return Results.BadRequest("Domain not allowed");

    var response = await http.GetAsync(uri);
    return response.IsSuccessStatusCode
        ? Results.Ok(new { status = "verified" })
        : Results.BadRequest("Could not reach URL");
});

async function registerWebhook(url) {
  const response = await fetch('/api/webhooks', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ callbackUrl: url })
  });

  const result = await response.json();
  if (!response.ok) {
    alert(result); // "Domain not allowed"
  }
}
